func orgTypeAr(t string) string {
	switch t {
	case "supplier", "vendor":
		return "مورّد / شركة أدوية"
	case "pharmacy":
		return "صيدلية / منشأة طبية"
	case "chain_pharmacy":
		return "سلسلة صيدليات"
	case "individual":
		return "حساب مهني فردي"
	default:
		return t
	}
}

